<?php require_once __DIR__.'/../model/auth_model.php';$m=new AuthModel();$u=$_SESSION['user'];$current=$m->byId($u['id']);$error='';$success='';if($_SERVER['REQUEST_METHOD']==='POST'){if(($_POST['type']??'')==='profile'){$n=trim($_POST['name']);$e=trim($_POST['email']);$p=trim($_POST['phone']);if(!$n||!filter_var($e,FILTER_VALIDATE_EMAIL))$error='Invalid profile data.';else{$m->update($u['id'],$n,$e,$p);$_SESSION['user']['name']=$n;$_SESSION['user']['email']=$e;$success='Profile updated.';}}else{$pw=$_POST['new_password'];if(strlen($pw)<6||$pw!==$_POST['confirm_password'])$error='Password must be 6+ characters and match confirmation.';else{$m->password($u['id'],$pw);$success='Password changed.';}}$current=$m->byId($u['id']);}require __DIR__.'/../views/profile.php';?>